export const grammarRu: Record<number, { title: string; explanation: string; examples: string[]; detailedExplanation?: string; tips?: string[]; comparisons?: string[] }> = {
  1: { title: "Базовый порядок слов SVO", explanation: "В китайском языке используется порядок «Подлежащее + Сказуемое + Дополнение», как в английском.", examples: ["Я ем.", "Он пьёт воду.", "Она читает."], detailedExplanation: "Китайский язык использует порядок подлежащего-сказуемого-дополнения (SVO), точно так же, как английский. Подлежащее (кто совершает действие) стоит первым, за ним следует глагол (само действие), и, наконец, дополнение (что подвергается действию). Например, в предложении '我吃苹果' (Я ем яблоко) '我' является подлежащим, '吃' — глаголом, а '苹果' — дополнением.\n\nЭта структура проста для начинающих, но китайский часто опускает подлежащее, когда контекст делает его очевидным, в отличие от английского, где подлежащее обычно требуется. Распространённая ошибка — добавлять лишние частицы или менять порядок, что делает предложения звучать неестественно.\n\nУпражняйтесь на простых, конкретных примерах, чтобы набраться уверенности. Начните с распространённых глаголов и постепенно добавляйте более сложные дополнения.", tips: ["Представьте, что китайский SVO имеет тот же порядок, что и в английском: Я + ем + рис.","Китайский часто опускает подлежащее, когда контекст делает его очевидным — это нормально, а не ошибка.","Сначала используйте простые дополнения: одиночные существительные перед фразами с существительными."], comparisons: ["В отличие от японского или корейского (порядок SOV), китайский ставит глагол перед дополнением, точно так же, как английский."] },
  2: { title: "Связка 是 между существительными", explanation: "是 (shì) связывает два существительных, как «это» или «является» в русском.", examples: ["Я студент.", "Он учитель.", "Это моя книга."] },
  3: { title: "Прилагательное-сказуемое с 很", explanation: "В китайском прилагательные выступают сказуемыми напрямую. 很 часто добавляется перед прилагательным, даже если не подразумевается «очень».", examples: ["У меня всё хорошо.", "Сегодня холодно.", "Китайская еда вкусная."], detailedExplanation: "В китайском языке прилагательные могут выступать в роли сказуемого предложения без глагола-связки, такого как 'есть'. Вы не говорите '我是高' (Я есть высокий) — вместо этого говорите '我很高' (Я высок). Слово 很 ставится перед прилагательным, но во многих случаях оно утратило свой буквальный смысл 'очень' и просто служит грамматическим 'клеем'.\n\nКогда вы действительно хотите подчеркнуть 'очень', вы можете произнести 很 с акцентом или использовать более сильные наречия, такие как 非常 или 特别. Без 很 или другого наречия прилагательное-сказуемое часто подразумевает сравнение: '他高' означает 'он высок (по сравнению с кем-то).'\n\nЭто одна из самых распространенных конструкций в повседневном китайском. Освоив её с ранних пор, вы сможете естественно описывать людей, погоду, еду и чувства.", tips: ["Не используйте 是 перед прилагательными — говорите 我很好, а не 我是好.","很 часто не означает 'очень' — это просто необходимый грамматический 'клеевой' элемент в нейтральных утверждениях.","Без 很 прилагательное подразумевает сравнение: 他高 = он выше (чем кто-то)."], comparisons: ["是 связывает существительные (我是学生), 很 связывает существительные с прилагательными (我很忙). Никогда не меняйте их местами.","Чтобы сказать 'очень' с акцентом, используйте 非常 или 特别 вместо произношения 很 с акцентом."] },
  4: { title: "Обладание с 有", explanation: "有 (yǒu) выражает обладание, как «иметь» в русском.", examples: ["У меня есть друг.", "У него двое детей.", "У тебя есть деньги?"], detailedExplanation: "有 (yǒu) выражает принадлежность — «иметь». Структура проста: Подлежащее + 有 + Объект. В отличие от английского, нет изменений для единственного/множественного числа или времени — 有 остается неизменным.\n\nОтрицание формы использует 没 вместо 不: «我没有钱» (У меня нет денег). Это важно, потому что большинство других глаголов используют 不 для отрицания, но 有 всегда сочетается с 没. Говорить «不有» всегда неправильно.\n\nЧасто между 有 и объектом ставятся количественные слова: «我有三个苹果» (У меня три яблока). Это также место, где вы практикуете меры, такие как 个, 本, 只.", tips: ["Отрицайте 有 с помощью 没, никогда не используйте 不. 我没有 — правильно, 我不有 — всегда неправильно.","有 не изменяется по времени — 我有 работает для прошлого, настоящего и будущего.","Добавляйте число + мера между 有 и объектом: 我有两本书."], comparisons: ["有 (принадлежность: У меня есть X) против 是 (идентичность: Я — X) — разные глаголы для разных значений.","有 использует 没 для отрицания; большинство других глаголов используют 不."] },
  5: { title: "Наличие с 有", explanation: "有 также выражает наличие — «есть», «имеется» что-то в каком-то месте.", examples: ["На столе лежит книга.", "В школе много учеников."] },
  6: { title: "Выделение деталей с 是…的", explanation: "Используется для выделения времени, места, способа или участника уже известного/совершённого действия.", examples: ["Когда ты приехал?", "Я прилетел на самолёте.", "Он учил китайский в Пекине."], detailedExplanation: "Конструкция 是…的 используется для подчеркивания конкретной детали о прошедшем действии, которое оба говорящий и слушатель уже знают произошло. Она выделяет, когда, где, как или кто — а не то, произошло ли действие.\n\nНапример, если кто-то уже знает, что вы посетили Китай, вы можете сказать '我是去年去的中国', чтобы подчеркнуть КОГДА (в прошлом году). Действие (поездка в Китай) предполагается известным; новая информация — это время. 是 ставится перед подчеркиваемой деталью, а 的 ставится в конце или рядом с ним.\n\nЧастая ошибка — использовать эту конструкцию для действий, которые еще не произошли или о которых слушатель не знает. Конструкция 是…的 применяется только для подчеркивания деталей известных прошедших событий.", tips: ["Используйте 是…的 только для прошедших действий, о которых оба говорящего знают — она выделяет, КАК/КОГДА/ГДЕ, а не ТО, ПРОИЗОШЛО ЛИ ДЕЙСТВИЕ.","是 ставится непосредственно перед деталью, которую вы хотите подчеркнуть.","的 обычно ставится в конце, но может стоять перед объектом: 我是在北京买的书 или 我是在北京买书的."], comparisons: ["是…的 подчеркивает детали прошедшего действия, тогда как 了 просто сообщает, что действие было завершено."] },
  7: { title: "Соединение существительных с 和", explanation: "和 (hé) соединяет два существительных, как «и». Не используется для соединения глаголов или предложений.", examples: ["я и ты", "Папа и мама оба учителя.", "Яблоки и вода на столе."], detailedExplanation: "和 (hé) соединяет два существительных, подобно «и» на английском языке. Однако, в отличие от английского «и», 和 может СОЕДИНЯТЬ ТОЛЬКО СУЩЕСТВИТЕЛЬНЫЕ ИЛИ ФРАЗЫ СУЩЕСТВИТЕЛЬНЫХ — НИКОГДА ГЛАГОЛЫ, ПРИЛАГАТЕЛЬНЫЕ ИЛИ ПРЕДЛОЖЕНИЯ. Чтобы сказать «Я пою и танцую», вы не можете использовать 和 между глаголами.\n\nПри соединении двух подлежащих с помощью 和, глагол, который следует за ними, часто включает 都 (оба/все), чтобы показать, что сказуемое относится ко всем элементам: «我和他都喜欢中国菜» (Он и я оба любим китайскую еду).\n\nДля соединения глаголов или предложений используйте другие союзы, такие как 也 (также), 还 (также/все еще) или просто перечислите действия последовательно.", tips: ["和 только для СУЩЕСТВИТЕЛЬНЫХ. Не используйте его для соединения глаголов или предложений.","После 和 добавьте 都, если сказуемое относится к обоим: «我和他都去» (Он и я оба идем).","Для перечисления 3+ элементов 和 ставится перед последним: A, B и C."], comparisons: ["和 соединяет только существительные. Для соединения действий используйте 也 (также) или перечислите их: «我唱歌跳舞» (Я пою и танцую)."] },
  8: { title: "Определение с 的", explanation: "的 (de) обозначает принадлежность или определяет существительное прилагательным, фразой или придаточным.", examples: ["моя книга", "красивая девушка", "Иероглифы, которые он пишет, очень красивые."], detailedExplanation: "的 (de) — один из самых часто используемых частиц в китайском языке. Он соединяет определение с существительным, охватывая обладание («моя книга»), описания прилагательными («красивая девушка») и даже описания на основе придаточных предложений («книга, которую он купил»).\n\nДля обладания структура такова: Местоимение + 的 + Существительное: 我的老师 (мой учитель). Для прилагательных: Прилагательное + 的 + Существительное: 好吃的菜 (вкусная еда). Для придаточных предложений всё предложение ставится перед 的: 他买的书 (книга, которую он купил).\n\nС близкими отношениями (семья, близкие друзья) и односложными прилагательными 的 часто опускается: 我妈妈 (моя мама), 好人 (хороший человек). Это естественно и распространено — не пытайтесь добавлять 的 в каждое определение.", tips: ["的 можно опустить при близких отношениях: 我妈妈 (моя мама), а не 我的妈妈.","Односложные прилагательные часто опускают 的: 好人, 大城市. Двусложные прилагательные сохраняют его: 漂亮的女孩.","Представьте, что 的 — это маркер обладания/описания, который стоит между описателем и описываемым предметом."], comparisons: ["的 (маркер обладания/описания) против 地 (маркер наречия перед глаголами) против 得 (степень дополнения после глаголов). Все произносятся как 'de', но используются по-разному."] },
  9: { title: "Отрицание с 不", explanation: "不 (bù) отрицает глаголы и прилагательные в настоящем или будущем времени. Не используется для прошедших действий.", examples: ["Я не пью кофе.", "Она несчастлива.", "Я не китаец."], detailedExplanation: "不 (bù) — это стандартное отрицание для глаголов и прилагательных в настоящем, будущем или привычном смысле. Располагайте 不 непосредственно перед глаголом или прилагательным: 我不喝咖啡 (Я не пью кофе), 她不高兴 (Она несчастлива).\n\nВажное правило тона: 不 обычно произносится на 4-й тон (bù), но меняется на 2-й тон (bú) при следовании за другим 4-й тоновой слогом. Например: 不是 произносится как 'bú shì', потому что 是 — 4-й тон.\n\nНЕ используйте 不 для прошлых действий — используйте 没 вместо этого. '我不去了' означает 'Я больше не пойду' (будущее решение), тогда как '我没去' означает 'Я не пошел' (прошлое событие).", tips: ["不 используется для отрицания настоящего/будущего/привычных действий. Для прошлых событий используйте 没.","Правило тона: 不 становится bú перед 4-й тоновой словами (不是 = bú shì).","不 ставится непосредственно перед глаголом: 我不知道, а не 我知道不."], comparisons: ["不 отрицает настоящие/будущие/привычные действия. 没 отрицает прошлые завершенные действия."] },
  10: { title: "Отрицание 有 с помощью 没", explanation: "有 всегда отрицается с 没, никогда с 不. 没有 означает «не иметь» или «нет».", examples: ["У меня нет денег.", "Здесь никого нет."], detailedExplanation: "有 (yǒu) — это особое глагол, который ВСЕГДА отрицается с помощью 没, никогда не с помощью 不. Говорить '不有' всегда грамматически неправильно в стандартном китайском языке. Отрицательная форма — 没有 (méiyǒu) или просто 没 (méi).\n\nЭто относится ко всем значениям 有: владение ('У меня нет...') и существование ('Здесь нет...'). 我没有车 (У меня нет машины), 这里没有水 (Здесь нет воды).\n\nВ разговорной речи 有 часто опускается после 没: 我没钱 = 我没有钱. Оба варианта естественны и правильны.", tips: ["НИКОГДА не говорите 不有 — это всегда 没有. Это #1 правило для 有.","没有 можно сократить до 没 в разговорной речи: 我没钱 = У меня нет денег.","没有 также означает 'не так... как' в сравнениях: 我没有他高 = Я не такой высокий, как он."], comparisons: ["有 → 没有 (никогда не 不有). Все другие глаголы → 不 или 没 в зависимости от времени."] },
  11: { title: "Отрицание прошлых действий с 没有", explanation: "没(有) отрицает совершённые действия — что-то не произошло в прошлом.", examples: ["Я не ходил.", "Он не завтракал.", "Она не пришла на урок."], detailedExplanation: "Чтобы сказать, что что-то НЕ произошло в прошлом, используйте 没(有) перед глаголом. Это отличается от 不, который отрицает действия в настоящем или будущем. 我没去 означает 'Я не пошел' (прошлое), тогда как 我不去 означает 'Я не пойду' (будущее).\n\nПри использовании 没 для отрицания прошлых действий НЕ добавляйте 了 после глагола. Поскольку 没 уже указывает, что действие не было завершено, 了 (который обозначает завершение) будет противоречить этому. Скажите 我没吃, а не 我没吃了.\n\nВ разговорной речи 有 после 没 можно опустить: 我没去 и 我没有去 означают одно и то же.", tips: ["Отрицание прошлого: 没 + глагол (без 了). 我没吃 = Я не съел.","Никогда не комбинируйте 没 и 了 с одним и тем же глаголом — они противоречат друг другу.","没有 можно сократить до 没: 我没去 = 我没有去."], comparisons: ["没 + глагол = не произошло (прошлое). 不 + глагол = не буду / не ем (настоящее/будущее)."] },
  12: { title: "«Не очень» с 不太", explanation: "不太 смягчает отрицание — «не очень», «не особо».", examples: ["Мне не очень нравится.", "Он не очень доволен."], detailedExplanation: "不太 — это вежливый, смягченный способ отрицания. Вместо резкого 不好 (не хорошо) фраза 不太好 (не очень хорошо) звучит мягче и более дипломатично. Китайская культура ценит косвенность, и 不太 является одним из ключевых инструментов для этого.\n\n不太 работает как с прилагательными (不太高兴 — не очень счастлив), так и с глаголами (不太喜欢 — не очень нравится). Это чрезвычайно распространено в повседневной речи, особенно при выражении мнений или отказе от предложений.\n\nОн также полезен, когда вы хотите выразить легкое неудовлетворение без грубости — 不太好吃 (не очень вкусно) гораздо мягче, чем 不好吃 (не вкусно).", tips: ["Используйте 不太, чтобы быть вежливым. 不太好 звучит гораздо мягче, чем 不好.","Работает с прилагательными И глаголами: 不太想去 = не очень хочется идти.","Часто используется при выражении мнений и отказах: 我不太方便 = Мне не очень удобно."], comparisons: ["不太 (не очень — мягко) против 不 (не — прямо) против 一点儿也不 (совсем не — сильно)."] },
  13: { title: "«Больше не» с 不…了", explanation: "Выражает изменение состояния — что-то больше не имеет места или не будет происходить.", examples: ["Я больше не ем.", "Он больше не пьёт."], detailedExplanation: "Паттерн 不…了 выражает ИЗМЕНЕНИЕ — что-то, что было правдой раньше, больше не верно, или было принято решение перестать. 我不吃了 означает 'Я больше не ем' (я ел, но решил остановиться или наелся).\n\nЗдесь 了 сигнализирует о смене состояния, а не о завершении. Без 了, 我不吃 просто означает 'Я не ем' как общее утверждение. С 了 это значит 'Я перестаю сейчас' или 'Больше не буду'.\n\nЭтот паттерн необходим для выражения решений, изменений мнения и ситуаций, которые изменились.", tips: ["不…了 = изменение по сравнению с прошлым. 我不吃了 = Я ел, но теперь перестаю.","Без 了 это просто общее отрицание: 我不吃 = Я не ем (в общем).","Используйте его для решений: 我不去了 = Я решил не идти (изменил мнение)."], comparisons: ["不吃 (не ем — общее) против 不吃了 (больше не ем — смена состояния)."] },
  14: { title: "Вопрос «да/нет» с 吗", explanation: "Добавьте 吗 (ma) в конец утверждения, чтобы превратить его в вопрос «да/нет».", examples: ["Вы учитель?", "Тебе нравится китайская еда?", "Он пришёл?"], detailedExplanation: "Простейший способ образования вопроса с ответом «да»/«нет» на китайском — добавить 吗 (ма) в конец утверждения. Порядок слов остается точно таким же — вы не переставляете ничего, как это делаете в английском языке («Вы учитель» → «Вы учитель?»).\n\nЭто одна из самых больших упрощений для изучающих язык: возьмите любое предложение, добавьте 吗, и оно станет вопросом. 他来了 (Он пришел) → 他来了吗? (Он пришел?). Важно, чтобы 吗 произносился с нейтральным тоном — всегда легким и без ударения.\n\nДля ответа повторите глагол для «да» (是 / 有 / 去) или отрицайте его для «нет» (不是 / 没有 / 不去). Не говорите 是 как универсальное «да» — соответствуйте глаголу из вопроса.", tips: ["Просто добавьте 吗 в конец любого утверждения — изменение порядка слов не требуется.","Отвечайте повторением глагола (да) или его отрицанием (нет), а не универсальным словом «да»/«нет».","Не используйте 吗 с вопросами типа A-не-A (你去不去? — они и так задают вопрос «да»/«нет».)"], comparisons: ["Вопросы с 吗 (нейтральные) против вопросов типа A-не-A (你去不去? — немного более прямые)."] },
  15: { title: "Вопрос «что» с 什么", explanation: "什么 (shénme) означает «что». Ставится на место ответа в предложении.", examples: ["Как тебя зовут?", "Что ты хочешь поесть?", "Что это?"] },
  16: { title: "Вопрос «кто» с 谁", explanation: "谁 (shéi) означает «кто». Заменяет человека в предложении.", examples: ["Кто он?", "Кто пришёл?"], detailedExplanation: "谁 (shéi) означает 'кто' и следует тому же правилу расположения, что и 什么. Он стоит точно там, где в ответе будет имя человека. 他是谁？ (Кто он?) → 他是我的老师 (Он мой учитель).\n\n谁 может быть как подлежащим, так и дополнением в предложении. Как подлежащее: 谁来了？ (Кто пришёл?). Как дополнение: 你找谁？ (Кого ты ищешь?). В обоих случаях не требуется изменения порядка слов.\n\nПримечание: 谁 иногда произносится как 'shuí' в более формальных контекстах, но 'shéi' — стандартное произношение в разговорной речи.", tips: ["谁 заменяет имя человека — ставьте его на то место, где будет имя в ответе.","Работает как подлежащее (谁来了?) или дополнение (你找谁?) без изменения порядка слов.","谁的 = чей: 这是谁的书？ = Чья это книга?"], comparisons: ["谁 (кто — спрашивает о личности) против 哪个人 (который человек — выбор из группы)."] },
  17: { title: "Вопрос «где» с 哪儿/哪里", explanation: "哪儿 (nǎr) или 哪里 (nǎlǐ) означает «где».", examples: ["Где ты живёшь?", "Где больница?"], detailedExplanation: "哪儿 (nǎr) и 哪里 (nǎlǐ) оба означают «где». 哪儿 чаще используется в северном Китае (особенно в Пекине), тогда как 哪里 предпочтительнее на юге. Оба варианта правильные и взаимозаменяемые в большинстве контекстов.\n\nОбычная структура — 在哪儿/哪里 (где). Как и другие вопросительные слова, они остаются на месте: 你在哪儿？ (Вы находитесь где?) вместо перемещения в начало предложения.\n\nТакже 哪里 имеет вежливое употребление: когда кто-то хвалит вас, ответ «哪里哪里» — это скромный способ отклонить комплимент. Это культурная идиома, а не буквальное «где-где».", tips: ["哪儿 (северный) = 哪里 (южный). Оба правильные, используйте тот, который вам удобнее.","Шаблон: Подлежащее + 在 + 哪儿: 你住在哪儿？ = Где вы живете?","哪里哪里 = вежливое отклонение комплиментов (культурная формула)."], comparisons: ["哪儿/哪里 (где — спрашивая о местоположении) против 哪个 (который — спрашивая о выборе)."] },
  18: { title: "Вопрос «когда» с 什么时候", explanation: "什么时候 (shénme shíhòu) означает «когда».", examples: ["Когда ты придёшь?", "Когда мы будем есть?"], detailedExplanation: "什么时候 (shénme shíhòu) буквально означает «какое время» и используется для вопроса «когда». Обычно он стоит ДО глагола в китайском, в отличие от английского, где «когда» начинает предложение.\n\nПорядок слов: Подлежащее + 什么时候 + Глагол. 你什么时候来？ = Ты когда приходишь? (Когда ты приезжаешь?). Это положение — между подлежащим и глаголом — является естественным для выражения времени в китайском языке.\n\nДля более конкретных вопросов о времени используйте 几点 (какой час/время) или 几月几号 (какой месяц и число). 什么时候 — самый общий вариант «когда» и подходит для любого временного диапазона.", tips: ["什么时候 стоит ДО глагола: 你什么时候走？ = Когда ты уходишь?","Он подходит для любого временного периода — прошлого, настоящего или будущего.","Для конкретного времени: 几点 (время суток), 几号 (дата), 星期几 (день недели)."], comparisons: ["什么时候 (когда — общий) против 几点 (какой час — конкретный)."] },
  19: { title: "Вопрос «как» с 怎么", explanation: "怎么 (zěnme) означает «как» или спрашивает о способе действия.", examples: ["Как пишется этот иероглиф?", "Как добраться до вокзала?"], detailedExplanation: "怎么 (zěnme) имеет два основных применения: вопрос о том, КАК (метод) и выражение удивления/недоверия.\n\nВопрос о методе: 怎么去？ (Как ты туда идёшь?), 这个字怎么写？ (Как пишется этот иероглиф?). Он ставится перед глаголом.\n\nВыражение удивления: 你怎么来了？ (Как ты сюда пришёл? / Почему ты здесь?). В этом случае 怎么 ближе к «как это так» — передаёт удивление или лёгкую жалобу, в отличие от 为什么, который является нейтральным «почему».", tips: ["怎么 + глагол = как (метод): 怎么做 = как это сделать.","怎么 также может означать «как это так» (удивление): 你怎么知道？ = Как ты это узнал?!","Для вопроса «как это» (мнение), используйте 怎么样 вместо: 这个怎么样？ = Как тебе это? (Как это?)"], comparisons: ["怎么 (как — метод/удивление) против 怎么样 (как — качество/мнение) против 为什么 (почему — нейтральная причина)."] },
  20: { title: "Вопрос «почему» с 为什么", explanation: "为什么 (wèishénme) означает «почему».", examples: ["Почему ты расстроен?", "Почему он не пришёл?"], detailedExplanation: "为什么 (wèishénme) спрашивает 'почему' и является одним из немногих вопросительных слов, которое может стоять как перед, так и после подлежащего. 你为什么不来？ и 为什么你不来？ оба грамматически правильны.\n\nЧтобы ответить на вопрос с 为什么, используйте 因为 (yīnwèi, 'потому что'). Полная структура — 因为...所以... (потому что... поэтому...), хотя в неформальной речи часто используется только 因为.\n\n为什么 — нейтральный, искренний вопрос о причинах. Для удивленного 'почему/как так получилось' более естественно использовать 怎么.", tips: ["为什么 может стоять перед или после подлежащего: 为什么你走？ = 你为什么走？","Ответьте с помощью 因为: 因为我累了 = Потому что я устал.","Для удивленного/раздраженного 'почему' используйте 怎么 вместо: 你怎么又迟到了？"], comparisons: ["为什么 (почему — нейтральный) против 怎么 (как так получилось — удивленный/эмоциональный)."] },
  21: { title: "Вопрос «какой» с 哪个", explanation: "哪个 (nǎ ge) означает «какой», «который».", examples: ["Какой тебе нравится?", "Который из них твой?"], detailedExplanation: "哪个 (nǎ ge) означает 'который' или 'который из', и используется при выборе из конкретного набора. В отличие от 什么 (что — открытый вопрос), 哪个 подразумевает наличие определенных вариантов.\n\nМера 个 может быть заменена на соответствующую для существительного: 哪本书 (которая книга), 哪个人 (который человек), 哪件衣服 (которая одежда).\n\n哪 отдельно (без меры) также сочетается с другими словами: 哪里 (где), 哪些 (которые — во множественном числе), 哪天 (какой день).", tips: ["哪个 = который из (из набора). 什么 = что (открытый вопрос).","Замените 个 на правильную меру: 哪本书, 哪件事, 哪位老师.","哪些 — множественное число: 你喜欢哪些？ = Какие тебе нравятся?"], comparisons: ["哪个 (который — выбор из вариантов) против 什么 (что — открытый вопрос)."] },
  22: { title: "Вопрос «сколько» с 几", explanation: "几 (jǐ) спрашивает «сколько», когда ожидается небольшое число (до 10).", examples: ["Сколько у тебя детей?", "Который сейчас час?"], detailedExplanation: "几 (jǐ) спрашивает «сколько» (обычно небольшое количество, обычно меньше 10). Он всегда требует меры после себя: 几个人 (сколько человек), 几本书 (сколько книг.\n\n几 также необходим для вопросов о времени: 几点 (который час), 几月 (какой месяц), 几号 (какой день), 星期几 (какой день недели). Это одни из самых часто используемых вопросов в повседневном китайском языке.\n\nВажное правило: 几 ДОЛЖЕН иметь меру. 多少 не требует её (хотя может её использовать).", tips: ["几 = ожидается небольшое количество (меньше 10). Всегда нужна мера.","Временные выражения: 几点 (время), 几月 (месяц), 几号 (дата), 星期几 (день недели).","你家有几口人？ — классический способ спросить о размере семьи."], comparisons: ["几 (сколько — небольшое количество, нужна мера) против 多少 (сколько/сколько много — любое количество, мера не обязательна)."] },
  23: { title: "Вопрос «сколько» с 多少", explanation: "多少 (duōshǎo) спрашивает «сколько» без ограничения по количеству.", examples: ["Сколько это стоит?", "Какой у тебя номер телефона?"], detailedExplanation: "多少 (duōshǎo) спрашивает «сколько» или «сколько стоит» без ограничения на ожидаемое количество. Используйте его для больших или неизвестных количеств. Мера количества не обязательна — можно использовать и 多少人, и 多少个人.\n\nНаиболее распространённое использование — спросить цену: 多少钱？ (Сколько стоит?). Это одна из первых фраз, которые должен знать каждый изучающий китайский язык.\n\n多少 также можно использовать для телефонных номеров, номеров комнат и других числовых идентификаторов: 你的电话号码是多少？ (Какой у вас телефонный номер?).", tips: ["Используйте 多少 для больших/неизвестных количеств, 几 — для небольших (менее 10).","多少钱？ = Сколько? (ключевая фраза для шопинга).","Мера количества не обязательна с 多少, но обязательна с 几."], comparisons: ["多少 (любое количество, мера количества не обязательна) против 几 (небольшое количество, мера количества обязательна)."] },
  24: { title: "Вопрос «как» о качестве с 怎么样", explanation: "怎么样 (zěnmeyàng) спрашивает «как?» — для мнений, состояний или предложений.", examples: ["Какая погода?", "Как эта книга?"], detailedExplanation: "怎么样 (zěnmeyàng) спрашивает мнение, оценку или состояние — «как это?» или «что ты думаешь?». Обычно используется в конце фразы или предложения.\n\nТри основные функции: спрашивая мнение (这个怎么样？ — Как насчет этого?), спрашивая о состоянии (你身体怎么样？ — Как твое здоровье?), и предлагая что-то (我们去吃饭怎么样？ — Как насчет того, чтобы пойти поесть?).\n\nНе путать с 怎么 (как — метод/удивление). 怎么样 спрашивает о качестве или мнении; 怎么 спрашивает о методе.", tips: ["Как использовать для мнений: 这部电影怎么样？ = Как вам фильм?","Используйте для предложений: 明天怎么样？ = Как насчет завтра?","Позиция: обычно в конце предложения или после темы."], comparisons: ["怎么样 (как это — мнение/качество) против 怎么 (как — метод) против 什么样 (какой — описание)."] },
  25: { title: "Вопрос о степени с 多", explanation: "多 (duō) перед прилагательным спрашивает о степени — насколько большой, сколько лет и т.д.", examples: ["Сколько тебе лет?", "Как далеко это?"], detailedExplanation: "多 (duō) перед прилагательным спрашивает о измеримой степени — насколько велико, насколько далеко, насколько стар, насколько высоко и т.д. Этот шаблон специально используется для прилагательных, описывающих измеримые величины.\n\nРаспространённые сочетания: 多大 (насколько стар / насколько велико), 多远 (насколько далеко), 多长 (насколько длинно), 多高 (насколько высоко), 多重 (насколько тяжело). Эти выражения необходимы для повседневного общения.\n\nПримечание: 多大 имеет два значения в зависимости от контекста — оно может спрашивать о возрасте (你多大？ = Сколько вам лет?) или о размере (这个房间多大？ = Какова площадь этой комнаты?).", tips: ["多 + прилагательное = спрашивая о степени: 多高 (насколько высоко), 多远 (насколько далеко).","多大 может означать 'сколько лет' ИЛИ 'насколько велико' — контекст определяет значение.","Работает только с измеримыми прилагательными, не с мнениями (не говорите 多好看)."], comparisons: ["多 + прилагательное (измеримая степень: 多高) против 怎么样 (мнение/качество: 怎么样?)."] },
  26: { title: "Вопросы с 了吗", explanation: "了吗 спрашивает, совершилось ли уже ожидаемое действие.", examples: ["Ты поел?", "Он ушёл?"] },
  27: { title: "«Тоже» с 也", explanation: "也 (yě) означает «тоже». Ставится перед глаголом, никогда в конце.", examples: ["Я тоже студент.", "Он тоже любит смотреть фильмы."], detailedExplanation: "也 (yě) означает 'тоже' или 'также' и ДОЛЖНО стоять перед глаголом — никогда не в конце предложения, как английское 'too'. Порядок слов: Подлежащее + 也 + Глагол. 我也去 (Я тоже пойду), никогда не 我去也.\n\nКогда используется с 都, 也 ставится перед: 他们也都来了 (Они тоже все пришли). Порядок всегда 也 перед 都.\n\n也 также может использоваться в отрицательных предложениях для усиления: 我也不知道 (Я тоже не знаю / Я тоже не знаю).", tips: ["也 ВСЕГДА ставится перед глаголом: 我也喜欢, никогда не 我喜欢也.","С 都: 也 ставится первым: 我们也都去了 (Мы тоже все пошли).","Отрицание: 我也不去 = Я тоже не пойду."], comparisons: ["也 (тоже — перед глаголом) против английского 'too' (в конце предложения). Ключевой момент — позиция."] },
  28: { title: "«Все» с 都", explanation: "都 (dōu) означает «все» или «оба». Ставится перед глаголом и относится к подлежащему.", examples: ["Мы все китайцы.", "Они все пришли.", "Мне всё это нравится."], detailedExplanation: "都 (dōu) означает «все» или «оба» и ставится перед глаголом, указывая на множественное подлежащее. 我们都去 (Мы все идём). Ключевое правило:都 суммирует то, что стоит ДО НЕГО, а не после.\n\nЭто означает, что множественное число должно стоять перед 都: 这些我都喜欢 (Эти, я все люблю = Я люблю все эти). Если сказать 我都喜欢这些, это будет звучать неправильно, потому что 都 не имеет перед собой ничего, что можно было бы суммировать.\n\n都 также может означать «даже» или «уже» в определенных конструкциях: 都八点了 (Уже 8 часов!), 连他都知道 (Даже он знает).", tips: ["都 суммирует то, что стоит ДО НЕГО, а не после. Множественное число идет первым.","С 也: порядок — 也都 (我们也都去了 = Мы тоже все пошли).","都 + время = «уже»: 都十点了! = Уже 10 часов!"], comparisons: ["都 (все — суммирует то, что перед ним) против 每 (каждый — ставится перед существительным: 每个人)."] },
  29: { title: "«Слишком» с 太…了", explanation: "太…了 (tài…le) означает «слишком» или «так» — выражает избыток или сильную эмоцию.", examples: ["Отлично!", "Это слишком дорого.", "Сегодня слишком жарко."], detailedExplanation: "太…了 (tài…le) имеет два применения в зависимости от контекста: «слишком много» (негативное превышение) и «так / действительно» (позитивное усиление).\n\nНегатив: 太贵了 (слишком дорого), 太难了 (слишком сложно). Частица 了 подчеркивает превышение.\n\nПозитив: 太好了！ (Это замечательно!), 太棒了！ (Отлично!). Здесь 太…了 используется как энтузиастическое усиление, а не для жалобы. Контекст и интонация определяют значение.\n\nБез 了, 太 по отдельности означает «слишком»: 不太好 (не очень хорошо). Частица 了 добавляет эмоциональной окраски.", tips: ["太 + adj + 了 = эмоциональное усиление. Контекст определяет, является ли это жалобой или похвалой.","太好了！ = Отлично! (позитив). 太贵了！ = Слишком дорого! (негатив).","Без 了: 不太 = не очень (мягче, см. пункт 12)."], comparisons: ["太…了 (сильное — слишком/так) против 很 (умеренное — очень) против 有点儿 (слабо негативное — немного)."] },
  30: { title: "«Немного» с 有点儿", explanation: "有点儿 (yǒudiǎnr) означает «немного» и обычно подразумевает что-то нежелательное.", examples: ["Я немного устал.", "Сегодня немного холодно."], detailedExplanation: "有点儿 (yǒudiǎnr) означает 'немного' и почти всегда описывает что-то НЕПРИЯТНОЕ или нежелательное. 我有点儿累 (Я немного устал), 有点儿贵 (немного дорого). Это подразумевает легкое неудовлетворение.\n\nНе путайте с 一点儿 (yìdiǎnr), который имеет другую структуру. 有点儿 ставится ПЕРЕД прилагательным (有点儿冷 — немного холодно). 一点儿 ставится ПОСЛЕ для сравнения (好一点儿 — немного лучше).\n\nВ северном китайском языке добавляется звук 儿 (er). В южном китайском люди говорят 有点 без 儿. Оба варианта правильные.", tips: ["有点儿 обычно описывает что-то негативное: 有点儿难, 有点儿贵, 有点儿累.","有点儿 ставится перед прилагательным. 一点儿 ставится после для сравнения.","Северный вариант: 有点儿. Южный вариант: 有点. Одинаковое значение."], comparisons: ["有点儿 (немного — негативно, перед прилагательным) против 一点儿 (немного — сравнение, после прилагательного)."] },
  31: { title: "«Снова» в будущем с 再", explanation: "再 (zài) означает «снова» для будущих или гипотетических действий.", examples: ["До свидания! (Увидимся снова)", "Пожалуйста, скажите ещё раз."] },
  32: { title: "«Ещё» / продолжение с 还", explanation: "还 (hái) означает «ещё», указывая на продолжение действия или что-то дополнительное.", examples: ["Он ещё спит.", "Что ещё ты хочешь?"], detailedExplanation: "还 (hái) имеет два основных значения: «ещё» (продолжающееся действие) и «также/дополнительно». \n\nЕщё: 他还在睡觉 (Он ещё спит). Действие ещё не закончилось.\n\nТакже/дополнительно: 你还要什么？ (Чего ещё ты хочешь?). Здесь 还 добавляет дополнительные элементы в список.\n\n还 также может означать «даже больше» в сравнениях: 他比我还高 (Он даже выше меня). А 还没 означает «ещё не»: 我还没吃 (Я ещё не поел).", tips: ["还在 + глагол = ещё делает: 还在工作 = ещё работает.","还没 = ещё не: 还没来 = ещё не пришёл.","还要 = также хочет / ещё хочет: 你还要什么？ = Чего ещё?"], comparisons: ["还 (ещё/также) против 再 (снова — будущее) против 又 (снова — прошлое)."] },
  33: { title: "Умеренная оценка с 还 + прилагательное", explanation: "还 перед положительным прилагательным означает «сносно» или «неплохо» — умеренно положительная оценка.", examples: ["Вкус неплохой.", "Ну, нормально."], detailedExplanation: "还 перед положительным прилагательным, таким как 好, 可以 или 不错, создает умеренно положительную оценку — 'неплохо' или 'не плохо'. Это менее энтузиастично, чем прямая похвала.\n\n还不错 (неплохо), 还可以 (нормально), 还好 (неплохо). Эти выражения очень распространены в повседневной речи, когда что-то приемлемо, но не выделяется.\n\nКультурная заметка: Китайская коммуникация часто использует сдержанность. Выражение 还不错 от китайского говорящего может на самом деле означать 'довольно хорошо' — они проявляют скромность. Контекст и тон имеют значение.", tips: ["还不错 = неплохо (умеренно положительная оценка). Очень распространено в неформальной речи.","还好 может означать 'к счастью': 还好你来了 = К счастью, ты пришел.","还可以 = нормально / приемлемо — часто используется, чтобы не звучать слишком негативно."], comparisons: ["还不错 (неплохо — умеренно) vs 很好 (отлично — энтузиастично) vs 不太好 (не очень хорошо — негативно)."] },
  34: { title: "Местонахождение с 在", explanation: "在 (zài) как глагол означает «находиться в/на (каком-то месте)».", examples: ["Он дома.", "Мой телефон на столе."] },
  35: { title: "Действие в месте с 在", explanation: "在 перед словом места указывает, где происходит действие.", examples: ["Я учусь в школе.", "Они едят в ресторане."], detailedExplanation: "Когда 在 используется как предлог (а не как главное глагол), он указывает НА КАКОМ МЕСТЕ происходит действие. Структура: Подлежащее + 在 + Место + Глагол. Место находится ДО глагола, в отличие от английского.\n\n我在学校学习 (Я учуся в школе) — '在学校' говорит, ГДЕ происходит учеба. Сравните с английским, где 'в школе' стоит после глагола.\n\nЭто фундаментальное различие в порядке слов. В китайском языке место (где), время (когда) и способ (как) всегда стоят ДО глагола. Представьте, что вы описываете обстановку, а потом действие.", tips: ["Место стоит ДО глагола: 在学校学习, а не 学习在学校.","Это относится ко всем фразам с местом: 在家做饭 = готовить дома.","Порядок слов в китайском: Время + Место + Глагол. Сначала обстановка, потом действие."], comparisons: ["在 + место + глагол (действие в месте) против 在 + место (нахождение в месте, пункт 34)."] },
  36: { title: "«Хотеть» с 想", explanation: "想 (xiǎng) означает «хотеть» или «хотелось бы».", examples: ["Я хочу выпить чая.", "Куда ты хочешь пойти?", "Я не хочу работать."], detailedExplanation: "想 (xiǎng) означает «хотеть» или «быть готовым» и является одним из самых полезных вспомогательных глаголов. Он ставится перед основным глаголом: 我想吃 (Я хочу есть).\n\n想 также используется для обозначения «думать» или «скучать»: 我想你 (Я скучаю по тебе), 我想一想 (Дайте мне подумать). Значение зависит от того, что следует за ним.\n\nДля отрицания: 不想 = не хочу. 我不想去 (Я не хочу идти). Это вежливый и прямой способ отказаться.", tips: ["想 + глагол = хочу. 想 + человек = скучать. 想 + 一想 = подумать.","Отрицание с помощью 不想: 我不想吃 = Я не хочу есть.","想 более мягкий, чем 要 (который более настойчивый/требовательный)."], comparisons: ["想 (хочу — мягче) против 要 (хочу/должен — настойчивее) против 需要 (нужно — необходимость)."] },
  37: { title: "Возможность с 能", explanation: "能 (néng) выражает возможность или способность — «мочь» в силу обстоятельств.", examples: ["Ты можешь прийти?", "Я сегодня не могу пойти."], detailedExplanation: "能 (néng) означает «может» в зависимости ОТ ОБСТОЯТЕЛЬСТВ или УСЛОВИЙ — у вас есть возможность или разрешение из-за ситуации. 你能来吗？ (Можешь ли ты прийти? — доступен/способен ли ты?).\n\n能 касается внешних факторов: здоровье, разрешение, время, физическая способность. 我今天不能去 (Сегодня я не могу пойти — я занят). 他病了，不能工作 (Он болен, не может работать).\n\nВ вопросах 能 часто используется для вежливых просьб: 你能帮我吗？ (Можешь ли ты мне помочь?). Это немного более формально, чем 可以.", tips: ["能 = может (обстоятельства позволяют). Не о навыках — это 会.","能不能 — распространённая форма вопроса A-не-A: 你能不能来？ = Можешь ли ты прийти?","Используется для вежливых просьб: 你能帮我吗？ = Мог бы ты мне помочь?"], comparisons: ["能 (может — обстоятельства) против 会 (может — навык) против 可以 (может — разрешение)."] },
  38: { title: "Приобретённый навык с 会", explanation: "会 (huì) выражает «уметь» — приобретённый навык, то, чему вы научились.", examples: ["Ты умеешь говорить по-китайски?", "Он умеет готовить.", "Я не умею водить машину."], detailedExplanation: "会 (huì) означает «может» как УСВОЕННАЯ СПОСОБНОСТЬ — то, чему вы учились или практиковались, чтобы уметь это делать. 你会说中文吗？ (Можете ли вы говорить по-китайски? — вы изучали это?).\n\nРазница между 会 и 能 крайне важна: 会开车 (умеете водить — усвоенная способность) против 能开车 (можете водить — обстоятельства позволяют, например, не пьяны). Человек может 会开车, но 不能开车, если его лицензия отозвана.\n\n会 также означает «будет» для прогнозов: 明天会下雨 (Завтра будет дождь). Контекст определяет значение.", tips: ["会 = усвоенная способность. Спрашивайте 你会...吗？ о навыках: плавание, готовка, языки.","会 также означает «будет» (прогноз): 他会来的 = Он придет.","不会 может означать «не умеет» (нет навыка) или «не придет» (прогноз): контекст определяет."], comparisons: ["会 (может — усвоенная) против 能 (может — обстоятельства) против 可以 (может — разрешение/разрешено)."] },
  39: { title: "Использование 对 с глаголами", explanation: "对 (duì) означает «по отношению к» — указывает на объект действия.", examples: ["Он очень хорошо ко мне относится.", "Учитель говорит ученикам."], detailedExplanation: "对 (duì) означает «к» или «в сторону» и указывает на цель или направление действия или отношения. 他对我很好 (Он очень хорошо относится КО МНЕ) — 对 отмечает «меня» как получателя доброты.\n\nРаспространенные конструкции: 对...好 (хорошо к), 对...说 (говорить кому-то), 对...有兴趣 (интересоваться чем-то), 对...不好 (плохо к). Лицо или предмет после 对 всегда является целью.\n\n对 также означает «правильно» как прилагательное: 对！ (Правильно!), 你说得对 (Вы сказали правильно).", tips: ["对 + person = к этому человеку. Отмечает цель действия.","对 как прилагательное = правильный: 对！= Правильно! 不对 = Неправильно.","对...感兴趣 = интересоваться чем-то: 我对中国文化感兴趣."], comparisons: ["对 (к/в сторону — цель) vs 给 (к/для — получатель) vs 跟 (с — спутник)."] },
  40: { title: "«Немного» / «попробовать» с 一下", explanation: "一下 (yíxià) смягчает глагол — «чуть-чуть», «на секунду».", examples: ["Подождите минутку.", "Дайте мне посмотреть.", "Попробуй."], detailedExplanation: "一下 (yíxià) после глагола делает действие коротким, неформальным или менее требовательным. 看一下 (беглый взгляд), 等一下 (немного подожди). Это как добавление 'всего' или 'немного' по-английски.\n\nЭто ключевой инструмент смягчения в китайском языке. Сравните: 你看 (Смотри! — резкий приказ) против 你看一下 (Посмотри — неформально, вежливо). Добавление 一下 делает просьбы гораздо более естественными и дружелюбными.\n\n一下 буквально означает 'один раз', но на практике оно просто смягчает. Не переводите его буквально — речь идет о тоне, а не о подсчете.", tips: ["Глагол + 一下 = сделать это кратко/неформально. Необходимо для вежливых просьб.","请等一下 и 我看一下 являются одними из самых полезных повседневных фраз.","Оно смягчает приказы: 说一下 (скажи кратко) мягче, чем 说！(Скажи!)."], comparisons: ["Глагол + 一下 (кратко/неформально) против глагол + 一点儿 (немного — степень/количество)."] },
  41: { title: "Результативный комплемент 完", explanation: "完 (wán) как результативный комплемент означает «закончить делать».", examples: ["Я доел.", "Ты дочитал эту книгу?"], detailedExplanation: "完 (wán) после глагола создает результативный дополнительный глагол, означающий «закончить что-то делать». 吃完 (закончить есть), 看完 (закончить читать/смотреть), 做完 (закончить делать). Действие было полностью завершено.\n\nОбычно используется вместе с 了: 我吃完了 (Я закончил есть). 了 подтверждает, что завершение действительно произошло. Без 了 это может использоваться в планах: 吃完饭去散步 (После того как закончу есть, пойду гулять).\n\nЧтобы спросить, закончил ли кто-то: Глагол + 完 + 了吗? 你看完了吗? (Ты закончил читать?). Чтобы сказать, что еще не закончено: 还没看完 (Еще не закончил читать).", tips: ["Глагол + 完 = закончить это действие: 吃完, 看完, 做完, 写完.","完了 = закончено. 还没完 = еще не закончено.","Используется для цепочки действий: 吃完饭以后去散步 = После того как поем, пойдем гулять."], comparisons: ["Глагол + 完 (закончить делать) против глагола + 好 (сделано правильно/готово) против глагола + 到 (достичь/добраться)."] },
  42: { title: "«Вместе» с 一起", explanation: "一起 (yìqǐ) означает «вместе».", examples: ["Давай поедим вместе.", "Хочешь пойти вместе?"], detailedExplanation: "一起 (yìqǐ) означает «вместе» и ставится перед глаголом. 我们一起吃饭 (Мы едим вместе). Это один из самых естественных способов пригласить кого-то на что-то.\n\nКлассическая формула приглашения: 我们一起 + глагол + 吧. 我们一起去吧 (Пойдём вместе). Добавление 吧 превращает это в предложение, а не приказ.\n\n一起 всегда ставится ДО глагола, между подлежащим и действием. Не ставьте его после глагола, как в английском языке «together».", tips: ["一起 ставится ДО глагола: 一起去, 一起吃, 一起学习.","Классическое приглашение: 我们一起...吧 = Давайте... вместе.","跟 + человек + 一起 = вместе с кем-то: 跟我一起去 = Пойдём со мной."], comparisons: ["一起 (вместе — действие) против 一块儿 (вместе — то же значение, более разговорное/северное)."] },
  43: { title: "Завершённое действие с 了", explanation: "了 (le) после глагола обозначает, что действие завершено.", examples: ["Я купил книгу.", "Он ушёл.", "Ты поел?"], detailedExplanation: "了 (le) после глагола обозначает ЗАВЕРШЕННОЕ ДЕЙСТВИЕ — что-то, что уже сделано. 我买了一本书 (Я купил книгу — покупка завершена). Это НЕ то же самое, что прошедшее время — 了 обозначает завершение, а не время.\n\nВы можете использовать 了 и для будущих завершений: 你吃了饭再走 (Сначала поешь, потом уходи — после того, как ты закончишь есть). Речь идет о том, что действие выполнено, а не о времени.\n\nВажно: 了 ставится сразу после глагола, перед объектом. С конкретным количеством: 我买了三本书 (Я купил три книги). Без 了 вы просто описываете действие в общем виде.", tips: ["了 = завершенное действие, НЕ прошедшее время. Может описывать и будущее завершение тоже.","Позиция: глагол + 了 + (количество) + объект: 买了两个苹果.","没 заменяет 了 для отрицания: 我没买 (Я не купил), а не 我没买了."], comparisons: ["Глагол + 了 (завершенное действие) против 了 в конце предложения (изменение состояния — пункт 44)."] },
  44: { title: "Новая ситуация с 了", explanation: "了 в конце предложения сигнализирует об изменении состояния — что-то стало иначе.", examples: ["Пошёл дождь.", "Я проголодался.", "Пришла весна."], detailedExplanation: "Конечный 了 указывает на ИЗМЕНЕНИЕ СОСТОЯНИЯ — что-то изменилось сейчас по сравнению с предыдущим. 下雨了 (Начался дождь — раньше не шёл). 我饿了 (Я голоден сейчас — раньше не был).\n\nЭто отличается от 了 после глагола (завершённое действие). Конечный 了 относится к текущему моменту. 春天来了 (Весна пришла — сезон изменился). 他长大了 (Он вырос — раньше был ребёнком).\n\nЭти два 了 могут сочетаться: 他吃了饭了 (Он поел — действие завершено + текущее состояние). Ученики часто путают их, но мысленно разделяя «завершение» и «изменение», это проще.", tips: ["Конечный 了 = сейчас всё иначе. 下雨了 = Идёт дождь (раньше не шёл).","Глагол + 了 = действие завершено. Конечный 了 = изменение состояния. Они могут быть вместе.","我饿了 = Я голоден ТЕПЕРЬ (изменение). 我吃了 = Я поел (завершение)."], comparisons: ["Глагол + 了 (завершённое действие — пункт 43) против конечного 了 (новая ситуация/изменение состояния)."] },
  45: { title: "Действие в процессе с 在", explanation: "在 или 正在 перед глаголом означает, что действие происходит прямо сейчас.", examples: ["Он смотрит телевизор.", "Я сейчас учу китайский.", "Мама готовит."] },
  46: { title: "Смягчение с 吧", explanation: "吧 (ba) смягчает высказывание или делает его предложением — «давай» или «наверное».", examples: ["Пойдём.", "Ну ладно.", "Ты ведь учитель, да?"], detailedExplanation: "吧 (ba) — это универсальная частица, которая ставится в конце предложения и имеет три основных применения: выражение предложения (давайте), смягчение утверждений и запрос подтверждения.\n\nПредложения: 我们走吧 (Давайте пойдём), 吃饭吧 (Давайте поедим). Это самый распространённый способ сказать «давайте» по-китайски.\n\nСмягчение/неохотное согласие: 好吧 (Хорошо, ладно — с некоторым неохотой). Частица 吧 придаёт ощущение уступчивости или смирения.\n\nЗапрос подтверждения: 你是中国人吧？ (Ты китаец, верно?). Это похоже на вопрос-тег — вы довольно уверены и хотите подтверждения.", tips: ["Глагол + 吧 = давайте: 走吧 (Давайте пойдём), 吃吧 (Давайте поедим).","好吧 = хорошо, ладно (неохотное согласие). Очень распространено в разговоре.","Утверждение + 吧 = запрос подтверждения: 你知道吧？ = Ты знаешь, верно?"], comparisons: ["吧 (мягкое предложение/подтверждение) против 吗 (искренний вопрос) против 呢 (что насчёт/продолжение состояния)."] },
  47: { title: "«Когда» с 的时候", explanation: "的时候 (de shíhòu) означает «когда» или «в то время как».", examples: ["Не разговаривай во время еды.", "Когда идёт дождь, я дома."] },
  48: { title: "«Всё» с 什么…都/也", explanation: "什么都 или 什么也 означает «всё» или «что угодно» (в зависимости от контекста).", examples: ["Он ест всё.", "Я ничего не хочу делать."] },
  49: { title: "Положение слов времени", explanation: "Слова времени могут стоять до или после подлежащего — оба варианта верны.", examples: ["Я пойду завтра.", "Вчера я не приходил."], detailedExplanation: "В китайском языке слова времени гибкие — они могут стоять перед или после подлежащего, и оба варианта правильны. 我明天去 = 明天我去 (Я пойду завтра / Завтра я пойду).\n\nКлючевое правило: время всегда стоит перед глаголом, никогда не после. Это противоположно английскому, где можно сказать «I go tomorrow». В китайском время задает обстановку перед действием.\n\nНесколько слов времени располагаются от большего к меньшему: 明天下午三点 (завтра в 3 часа дня). Год → месяц → день → время суток → час.", tips: ["Время может стоять перед или после подлежащего, но ВСЕГДА перед глаголом.","От большего к меньшему: 明天下午三点 = завтра в 3 часа дня.","Распространенные слова времени: 今天 (сегодня), 明天 (завтра), 昨天 (вчера), 现在 (сейчас)."], comparisons: ["Китайский: Время перед глаголом (我明天去). Английский: Время после глагола (I go tomorrow)."] },
  50: { title: "«После» с 以后", explanation: "以后 (yǐhòu) означает «после» определённого времени или события.", examples: ["После обеда пойдём гулять.", "После трёх я свободен."] },
  51: { title: "«До» с 以前", explanation: "以前 (yǐqián) означает «до» определённого времени или события.", examples: ["До приезда в Китай я не говорил по-китайски.", "Перед сном нужно чистить зубы."] },
  52: { title: "Структура даты", explanation: "Дата идёт от большего к меньшему: год, месяц, день.", examples: ["1 января 2025 года", "Какого числа твой день рождения?"], detailedExplanation: "Китайские даты идут от БОЛЬШЕГО к МЕНЬШЕМУ: год → месяц → день. Это противоположно американскому формату (месяц/день/год), но соответствует китайской логике — большее перед меньшим.\n\n年 (nián) = год, 月 (yuè) = месяц, 日 (rì) или 号 (hào) = день. 日 используется в официальных/письменных текстах, 号 — в разговорной речи. Для повседневного использования говорите 号.\n\nМесяцы просто нумеруются: 一月 (январь = месяц 1), 二月 (февраль = месяц 2) и т.д. Не нужно запоминать отдельные названия месяцев, как в английском языке.", tips: ["Большее → меньшее: 2025年1月1号. Сначала год, потом месяц, затем день.","Месяцы = цифры: 一月 до 十二月. Просто!","号 (разговорный/устный) против 日 (официальный/письменный) для дня."], comparisons: ["Китайский: год-месяц-день (大到小). Американский: месяц/день/год. Европейский: день.месяц.год."] },
  53: { title: "Структура времени (часы)", explanation: "Время обозначается с 点 (diǎn) для часов и 分 (fēn) для минут.", examples: ["Сейчас полчетвёртого.", "Мой урок начинается в 8 часов."] },
  54: { title: "Счётное слово 个", explanation: "个 (gè) — самое распространённое счётное слово. Используйте его, если не знаете специального счётного слова.", examples: ["один человек", "три яблока", "сколько студентов"], detailedExplanation: "个 (gè) — это универсальная мера счета. В китайском языке требуется мера счета между числительным и существительным — вы не можете сказать 三苹果 (три яблока), нужно 三个苹果.\n\nУ каждого существительного есть «правильная» мера счета (本 для книг, 只 для животных, 件 для одежды), но 个 работает как универсальный резервный вариант. Носители языка используют конкретные меры счета, но использование 个, когда вы не уверены, абсолютно понятно.\n\nНа уровне HSK1 сосредоточьтесь на изучении 个. По мере продвижения постепенно осваивайте конкретные меры счета. Даже носители иногда используют 个 как неформальный упрощенный вариант.", tips: ["Всегда используйте меру счета между числительным и существительным. 个 — это безопасный универсальный вариант.","一个人 (один человек), 两个苹果 (два яблока), 三个问题 (три вопроса).","Если сомневаетесь, используйте 个. Лучше использовать его, чем не использовать меру счета вообще."], comparisons: ["个 (общая мера) против 本 (книги) против 只 (животные) против 件 (одежда/вопросы) против 杯 (чашки)."] },
  55: { title: "Возраст с 岁", explanation: "岁 (suì) — счётное слово для возраста, глагол не нужен.", examples: ["Мне двадцать лет.", "Его дочери пять лет."], detailedExplanation: "Чтобы указать возраст на китайском, просто скажите число + 岁 — глагол 'быть' не нужен. 我二十岁 (Мне 20 лет). Это проще, чем по-английски.\n\nДобавление 了 подчеркивает, что возраст недавно был достигнут или является значимым: 他五岁了 (Он уже пятилетний / Он только что стал пятилетним). Без 了 это нейтральное утверждение возраста.\n\nРазные способы спросить возраст: 你多大？ (неформально, для сверстников), 你几岁？ (для детей до 10 лет), 您多大年纪？ (уважительно, для пожилых людей).", tips: ["Число + 岁 = возраст. Не нужно 是: 我二十岁, а не 我是二十岁.","你多大？ (для сверстников) против 你几岁？ (для детей) против 您多大年纪？ (для пожилых людей).","Добавление 了: 他十八岁了 = Он только что стал восемнадцатилетним (акцент на достижение возраста)."], comparisons: ["岁 (возраст) против 年 (продолжительность времени): 我学了三年 (учился 3 года) против 我三十岁 (мне 30 лет)."] },
  56: { title: "Счёт денег", explanation: "块 (kuài) — разговорное слово для юаней, 毛 (máo) — для цзяо (десятых юаня).", examples: ["десять юаней", "три с половиной юаня"], detailedExplanation: "Китайская валюта использует три единицы: 元/块 (yuán/kuài), 角/毛 (jiǎo/máo), 分 (fēn). 块 и 毛 являются разговорными/устными формами; 元 и 角 — формальными/письменными.\n\n块 = юань (как доллары), 毛 = 1/10 юаня (как десятицентовые монеты), 分 = 1/100 юаня (как центы, редко используется сейчас). 三块五 означает 3,50 юаня — можно опустить 毛, если смысл ясен.\n\n钱 (qián) означает 'деньги' и часто добавляется в конце: 十块钱 (10 юаней). Ключевая фраза для шопинга: 多少钱？ (Сколько стоит?).", tips: ["块 (разговорное) = 元 (письменное). Оба означают юань, единицу валюты Китая.","三块五 = 3,50 юаня. Можно опустить 毛, если это очевидно из контекста.","多少钱？ и 太贵了！ — две ключевые фразы для шопинга."], comparisons: ["块/元 (юань — доллары) против 毛/角 (десятицентовые монеты) против 分 (центы — редко используется)."] },
  57: { title: "Порядковые числительные с 第", explanation: "第 (dì) превращает число в порядковое — первый, второй, третий и т.д.", examples: ["первый", "третий человек", "Это мой первый раз в Китае."], detailedExplanation: "第 (dì) превращает любое число в порядковое: 第一 (первый), 第二 (второй), 第三 (третий). Просто добавьте 第 перед числом — это так просто.\n\nС существительным добавьте соответствующий меры: 第三个人 (третий человек), 第一本书 (первая книга), 第二次 (второй раз).\n\n次 (cì, 'раз/случай') особенно часто используется с 第: 第一次 (в первый раз). Это одна из самых полезных фраз для путешественников: 这是我第一次来中国.", tips: ["第 + число = порядковое: 第一 (1-й), 第二 (2-й), 第三 (3-й).","第 + число + мера + существительное: 第三个人 = третий человек.","第一次 = в первый раз. Необходимая фраза для новых впечатлений."], comparisons: ["第 + число (порядковое: 第三 = третий) против простого числа (кардинальное: 三 = три)."] },
  58: { title: "«Несколько» с 一些", explanation: "一些 (yìxiē) означает «несколько» или «немного».", examples: ["У меня есть несколько вопросов.", "Дайте мне немного воды."], detailedExplanation: "一些 (yìxiē) означает 'некоторые' или 'несколько' и не требует меры — оно сразу ставится перед существительным. 一些人 (некоторые люди), 一些问题 (некоторые вопросы).\n\nВ разговорной речи часто опускается 一: 有些人 (некоторые люди) = 有一些人. Само по себе 些 не работает — ему нужен 一 или 有 перед собой.\n\n一些 используется как для исчисляемых, так и для неисчисляемых существительных: 一些水 (немного воды), 一些朋友 (некоторые друзья). Оно менее конкретно, чем число, и подразумевает 'умеренное количество'.", tips: ["一些 + существительное напрямую, мера не нужна: 一些书, 一些时间.","有些 = 有一些 (некоторые). Сокращение в разговорной речи.","Работает для исчисляемых и неисчисляемых: 一些人, 一些水."], comparisons: ["一些 (некоторые — умеренное) против 几个 (несколько — небольшое число) против 很多 (много/многое)."] },
  59: { title: "Разрешение с 可以", explanation: "可以 (kěyǐ) выражает разрешение («можно») или возможность. Отрицание — 不可以 (нельзя).", examples: ["Можно мне войти?", "Здесь нельзя курить."], detailedExplanation: "可以 (kěyǐ) означает «можно» или «могу» в смысле РАЗРЕШЕНИЯ или ДОПУСТИМОСТИ. 我可以进来吗？ (Могу ли я войти?). Это касается разрешения на действие, а не навыка или обстоятельств.\n\nОтрицание с помощью 不可以 для запрета: 这里不可以抽烟 (Здесь нельзя курить — это не разрешено). Это сильнее, чем 不能, при выражении правил.\n\n可以 также может означать «приемлемо/неплохо» как прилагательное: 还可以 (всё нормально), 味道可以 (вкус неплох).", tips: ["可以 = разрешено/можно. Используйте для вопросов о разрешении: 可以吗？ = Это разрешено?","不可以 = не разрешено (запрет). Сильнее, чем 不能, при выражении правил.","可以 как прилагательное: 还可以 = всё нормально / приемлемо."], comparisons: ["可以 (можно — разрешение) против 能 (можно — обстоятельства) против 会 (можно — усвоенный навык)."] },
  60: { title: "Сравнение с 比", explanation: "比 (bǐ) сравнивает две вещи. После 比 прилагательное не может использовать 很.", examples: ["Он выше меня.", "Сегодня холоднее, чем вчера.", "Китайский сложнее английского."], detailedExplanation: "比 (bǐ) — это стандартное слово для сравнения. A 比 B + прилагательное = A больше [прилагательное], чем B. ВАЖНО: не используйте 很 с 比 — скажите 他比我高, НЕ 他比我很高.\n\nЧтобы выразить «насколько», добавьте количество после прилагательного: 他比我高五厘米 (Он выше меня на 5 см). Часто используются 多 и 一点儿: 他比我大两岁 (Он старше меня на 2 года).\n\nДля отрицания используйте 没有 вместо 不比. 我没有他高 (Я не такой высокий, как он). 不比 существует, но означает «не больше чем» — нюанс.", tips: ["НИКОГДА не используйте 很 с 比. Скажите 比我高, а не 比我很高.","Добавляйте количество после прилагательного: 比我大三岁 = старше меня на 3 года.","Отрицайте с помощью 没有: 我没有他高 = Я не такой высокий, как он."], comparisons: ["比 (A больше, чем B) против 没有 (A не так много, как B) против 一样 (A равно B)."] },
  61: { title: "«Такой же, как» с 一样", explanation: "一样 (yíyàng) означает «одинаковый». Используйте 跟 или 和 для связи сравниваемых объектов.", examples: ["Я такого же роста, как ты.", "Этот такой же, как тот.", "Его телефон такой же, как мой."], detailedExplanation: "一样 (yíyàng) означает «такой же» и используется с 跟 или 和 для сравнения двух вещей как равных. A 跟 B 一样 = A такое же, как B. Добавьте прилагательное для конкретного сравнения: A 跟 B 一样高 (A такой же высокий, как B).\n\nДля отрицания: A 跟 B 不一样 (A и B разные). Это очень распространено в разговоре для указания различий.\n\n跟 и 和 взаимозаменяемы в этом случае. 跟 немного более неформален; 和 более нейтрален/письменный. Оба правильны.", tips: ["A 跟 B 一样 = такое же. A 跟 B 不一样 = разные.","A 跟 B 一样 + adj = одинаково: 跟你一样高 = такой же высокий, как ты.","跟 и 和 взаимозаменяемы в этой конструкции."], comparisons: ["一样 (равно) против 比 (больше чем) против 没有 (не так много, как)."] },
  62: { title: "Превосходная степень с 最", explanation: "最 (zuì) означает «самый». Ставится непосредственно перед прилагательным или глаголом.", examples: ["Она самая красивая.", "Больше всего я люблю китайскую еду.", "Этот самый дешёвый."], detailedExplanation: "最 (zuì) создает превосходные степени — «самый» или «-ей». Просто поставьте 最 перед любым прилагательным или глаголом: 最大 (самый большой), 最喜欢 (самый любимый), 最好 (самый лучший).\n\nВ отличие от английского, не нужно запоминать неправильные формы. 好 → 最好 (самый лучший), 多 → 最多 (самое много), 快 → 最快 (самый быстрый). Всегда просто 最 + слово.\n\nС конструкцией 是...的: 她是最漂亮的 (Она самая красивая). Частица 的 превращает фразу — «самая красивая».", tips: ["最 + любое прилагательное/глагол = превосходная степень. Нет неправильных форм!","最好 = самое лучшее. Также используется для совета: 你最好... = Ты лучше...","最 + глагол: 我最喜欢 = Я люблю (это) больше всего."], comparisons: ["最 (превосходная степень — самый) vs 更 (сравнительная степень — еще более) vs 比 (сравнение — больше, чем)."] },
  63: { title: "«Ещё более» с 更", explanation: "更 (gèng) означает «ещё более». Подчёркивает более высокую степень, чем ожидалось.", examples: ["Завтра будет ещё холоднее.", "Я хочу найти ещё лучшую работу.", "Он ещё выше меня."] },
  64: { title: "«Чуть больше» с 一点儿", explanation: "一点儿 (yìdiǎnr) после сравнения означает «чуть-чуть больше». Часто используется с 比 или в просьбах.", examples: ["Пожалуйста, говорите чуть медленнее.", "Этот чуть больше того.", "Подешевле, пожалуйста."], detailedExplanation: "更 (gèng) означает «ещё больше» и усиливает сравнение. Его можно использовать с или без 比: 明天会更冷 (Завтра будет ещё холоднее), 他比我更高 (Он ещё выше меня).\n\nНюанс: 更 подразумевает более высокую степень, чем уже ожидалось. 好 (хорошо) → 更好 (ещё лучше) подразумевает, что это уже было хорошо.\n\n一点儿 (yìdiǎnr) после сравнительной формы означает «немного больше». 请说慢一点儿 (Пожалуйста, говорите немного медленнее). 便宜一点儿 (немного дешевле) — обязательно для торговли!", tips: ["更 = ещё больше, сверх того, что уже есть.","更 может использоваться самостоятельно или с 比: 更好 или 比他更好.","一点儿 после прилагательного = немного больше: 大一点儿, 便宜一点儿."], comparisons: ["更 (ещё больше — идёт дальше) против 比 (сравнение) против 最 (превосходная степень — абсолютный максимум)."] },
  65: { title: "Причина и следствие с 因为…所以", explanation: "因为 (yīnwèi) означает «потому что», а 所以 (suǒyǐ) — «поэтому». Можно использовать одно или оба.", examples: ["Из-за дождя я не пошёл.", "Он заболел, поэтому не пришёл на занятия.", "Я устал, поэтому хочу отдохнуть."], detailedExplanation: "因为...所以... — это стандартная структура «потому что... поэтому...». В отличие от английского, китайский часто использует ОБЕ части вместе. В английском вы скажете: «Потому что шел дождь, я не пошел» — но использование «потому что» И «поэтому» в одном предложении звучит избыточно. В китайском это естественно.\n\nВы можете использовать любую часть отдельно: 因为下雨了，我没去 (Потому что шел дождь, я не пошел) или 我很累，所以想休息 (Я устал, поэтому хочу отдохнуть).\n\nПри ответе на вопросы 为什么 начинайте с 因为: 为什么没来？因为我生病了。", tips: ["Использование обеих частей 因为 и 所以 вместе естественно в китайском, а не избыточно.","Любая часть может использоваться отдельно: 因为... или ...所以...","Отвечайте на 为什么 с помощью 因为: 为什么？因为太贵了。"], comparisons: ["因为...所以 (причина-следствие) против 虽然...但是 (уступка — хотя...но)."] },
  66: { title: "Противопоставление с 虽然…但是", explanation: "虽然 (suīrán) означает «хотя», а 但是 (dànshì) — «но». Контраст идёт вторым.", examples: ["Хотя дорого, но вкусно.", "Хотя он занят, он всё равно пришёл.", "Хотя трудно, я хочу попробовать."], detailedExplanation: "虽然...但是... означает «хотя...но...» и является одной из ключевых особенностей, отличающих китайский от английского — в китайском используют ОБА слова «хотя» и «но» вместе. В английском предложение «Although it's expensive, but it's delicious» является неправильным. В китайском это стандартная структура.\n\nКлауза 虽然 идет первой (уступка), а 但是 вводит основную мысль. Основное внимание говорящего направлено на часть после 但是.\n\n可是 (kěshì) может заменить 但是 в неформальной речи. 不过 (búguò) еще мягче — «однако». Все три выражения означают «но», с уменьшающейся формальностью.", tips: ["Используйте ОБА слова 虽然 и 但是 вместе — это правильный китайский, в отличие от английского.","Основная мысль находится в части после 但是, а не в части с 虽然.","但是 (формальный) = 可是 (неформальный) = 不过 (мягкий). Все означают «но»."], comparisons: ["虽然...但是 (хотя...но — уступка) против 因为...所以 (потому что...поэтому — причина)."] },
  67: { title: "«Кроме» с 除了…以外", explanation: "除了…以外 (chúle…yǐwài) означает «кроме» или «за исключением». 都 исключает, 也/还 включает.", examples: ["Кроме него, мы все пошли.", "Кроме китайского, она ещё говорит по-английски."], detailedExplanation: "除了...以外 означает «кроме» или «за исключением». Ключевое значение в том, что следует далее: 都 означает ИСКЛЮЧАЯ (все, кроме X), тогда как 也/还 означает ВКЛЮЧАЯ (в дополнение к X).\n\nИсключение: 除了他以外，我们都去了 (Кроме него, мы все пошли — он не пошел).\nВключение: 除了中文以外，她还会说英文 (Кроме китайского, она также говорит по-английски — она говорит на обоих языках).\n\nВ неформальной речи часто опускают 以外: 除了他，我们都去了.", tips: ["除了 + 都 = кроме (исключая). 除了 + 也/还 = кроме (включая).","以外 можно опустить в неформальной речи: 除了他都去了.","Этот шаблон часто используется при перечислении: 除了周末以外，我每天都工作."], comparisons: ["除了...都 (кроме — исключая) vs 除了...也/还 (кроме — включая)."] },
  68: { title: "«Или» с 还是 и 或者", explanation: "还是 (háishi) используется в вопросах с выбором. 或者 (huòzhě) — в утверждениях.", examples: ["Тебе чай или кофе?", "Завтра или послезавтра — всё равно.", "Ты едешь на автобусе или на метро?"], detailedExplanation: "还是 и 或者 оба означают 'или', но в разных контекстах.还是 используется в ВОПРОСАХ (предлагая выбор), или используется в УТВЕРЖДЕНИЯХ (перечисляя альтернативы).\n\n还是: 你喝茶还是咖啡？ (Чай или кофе? — выберите один). Используется только в вопросах.\n或者: 明天或者后天都可以 (Завтра или послезавтра, оба варианта подходят). Используется в утверждениях.\n\nЧастая ошибка — перепутать их. Помните: 还是 = вопросительное 'или', 或者 = утверждение 'или'.", tips: ["还是 для вопросов: 你去还是不去？ = Идёте вы или нет?","或者 для утверждений: 我想去北京或者上海 = Я хочу поехать в Пекин или Шанхай.","Никогда не меняйте их местами — использование 还是 в утверждении или 或者 в вопросе звучит неправильно."], comparisons: ["还是 (или — в вопросах) против 或者 (или — в утверждениях)."] },
  69: { title: "«Не только…но и» с 不但…而且", explanation: "不但 (búdàn) означает «не только», а 而且 (érqiě) — «но и». Б — более сильный аргумент.", examples: ["Он не только говорит по-китайски, но и говорит очень хорошо.", "Это место не только красивое, но и очень тихое."], detailedExplanation: "不但...而且... означает «не только... но и...» и используется для добавления ВТОРОГО, БОЛЕЕ СИЛЬНОГО или важного пункта. Часть с 而且 должна быть более впечатляющей или важной, чем часть с 不但.\n\n他不但会说中文，而且说得很好 — второй пункт (говорит хорошо) сильнее первого (может говорить). Эта эскалация ключевая.\n\nВ неформальной речи часто используется только 而且 (без 不但): 他很聪明，而且很努力 (Он умный, и к тому же очень трудолюбив).", tips: ["Часть с而且 должна быть более сильной/впечатляющей точкой.","Использование 而且 отдельно очень распространено: 好吃，而且便宜 = Вкусно, и также дешево.","Один субъект: 他不但...而且... Разные субъекты: 不但他...而且我们都..."], comparisons: ["不但...而且 (не только... но и — эскалация) против 虽然...但是 (хотя... но — контраст)."] },
  70: { title: "«Уже» с 已经…了", explanation: "已经 (yǐjīng) означает «уже». 了 в конце подтверждает изменение состояния.", examples: ["Я уже поел.", "Он уже ушёл.", "Фильм уже начался."], detailedExplanation: "已经...了 обозначает, что что-то уже произошло или что состояние уже достигнуто. Частица 了 подтверждает, что изменение завершено.\n\n已经 ставится перед глаголом, 了 — в конце: 我已经吃了 (Я уже поел). Комбинация подчеркивает «это сделано, беспокоиться не нужно».\n\nПолезно для вежливого отказа: 我已经吃了 (Я уже поел — когда предлагают еду). Также для выражения прошедшего времени: 已经十点了 (Уже десять часов).", tips: ["已经 + глагол +了 = уже сделано: 已经到了 = уже прибыл.","已经 + время +了 = уже: 已经很晚了 = Уже поздно.","Отрицание с помощью 还没: 还没吃 = ещё не ел (не 已经没吃)."], comparisons: ["已经...了 (уже — завершено) против 还没 (ещё не — ожидается) против 刚 (только что — недавно)."] },
  71: { title: "«Только что» с 刚 и 刚才", explanation: "刚 (gāng) означает «только что» и ставится перед глаголом. 刚才 (gāngcái) означает «только что» и может стоять перед подлежащим или глаголом.", examples: ["Я только что приехал.", "Он только что тебе звонил.", "Она только что поела."], detailedExplanation: "刚 (gāng) и 刚才 (gāngcái) оба означают «только что», но используются по-разному. 刚 — это наречие, которое ставится непосредственно перед глаголом: 我刚到 (Я только что приехал). 刚才 — это слово времени, которое может стоять перед подлежащим или глаголом: 刚才他打电话了.\n\nКлючевое различие: 刚 подчеркивает недавность и не использует 了. 刚才 — это указание на время и часто сочетается с 了.\n\nНе добавляйте 了 после 刚: говорите 我刚到, а не 我刚到了. 刚 уже подразумевает «только что произошло», поэтому 了 избыточен.", tips: ["刚 + глагол (без 了): 我刚到, 我刚吃完.","刚才 — это слово времени, может стоять перед подлежащим: 刚才谁来了？","刚 = акцент на «только что» (секунды назад). 刚才 = «недавно» (минуты)."], comparisons: ["刚 (только что — перед глаголом, без 了) против 刚才 (только что — слово времени, с 了)."] },
  72: { title: "«Наконец» с 终于", explanation: "终于 (zhōngyú) означает «наконец». Подразумевает долгое ожидание.", examples: ["Ты наконец пришёл!", "Я наконец нашёл это.", "Дождь наконец прекратился."], detailedExplanation: "终于 (zhōngyú) означает «наконец/наконец-то» и всегда подразумевает долгое ожидание или усилие. Здесь есть эмоциональная составляющая — облегчение, удовлетворение или иногда разочарование.\n\n你终于来了！ (Ты наконец-то пришёл!) выражает облегчение после ожидания. 我终于找到了 (Я наконец-то нашёл) подразумевает поиски, которые потребовали усилий.\n\n终于 обычно сочетается с 了 в конце — 了 обозначает изменение состояния (от ожидания к завершению). Без эмоции или ожидания не используйте 终于.", tips: ["终于 подразумевает ожидание/усилие. Не используйте для рутинных событий.","终于 + глагол + 了: 终于下课了！ = Урок наконец-то закончился!","Передаёт эмоцию: облегчение (终于好了), досаду (终于来了…)."], comparisons: ["终于 (наконец — после долгого ожидания) против 已经 (уже — нейтральное завершение)."] },
  73: { title: "«Часто» с 常常 и 经常", explanation: "常常 (chángcháng) и 经常 (jīngcháng) оба означают «часто». В большинстве случаев взаимозаменяемы.", examples: ["Я часто хожу в тот ресторан.", "Он часто опаздывает.", "Она часто мне помогает."], detailedExplanation: "常常 (chángcháng) и 经常 (jīngcháng) оба означают 'часто' и взаимозаменяемы. 常常 немного более неформален/разговорен; 经常 немного более формален, но всё равно очень часто используется в речи.\n\nОба ставятся перед глаголом: 我常常去 (Я часто хожу). Они описывают привычные действия — то, что вы регулярно делаете.\n\nОтрицание: не часто/не часто — 不常/不经常: 我不常去 (Я не часто хожу). Для 'никогда' используйте 从来不: 我从来不去 (Я никогда не хожу).", tips: ["常常 ≈ 经常. Оба означают 'часто'. Используйте то, что кажется естественным.","Позиция: перед глаголом. 我常常运动 = Я часто занимаюсь спортом.","Лестница частоты: 从来不 (никогда) < 不常 (не часто) < 有时候 (иногда) < 常常 (часто) < 总是 (всегда)."], comparisons: ["常常/经常 (часто) vs 有时候 (иногда) vs 总是 (всегда)."] },
  74: { title: "«Всегда» / «всё время» с 一直", explanation: "一直 (yìzhí) означает «всегда» или «непрерывно» — действие, которое продолжается без остановки.", examples: ["Я всё это время тебя ждал.", "Он всегда жил в Пекине.", "Она всегда была трудолюбивой."], detailedExplanation: "一直 (yìzhí) означает «всегда» в смысле НЕПРЕРЫВНО — действие или состояние, которое продолжается без перерыва. 我一直在等你 (Я жду тебя всё время — непрерывно, без остановки).\n\nЭто отличается от 总是 (zǒngshì, «всегда» в смысле привычного действия). 一直 подчеркивает непрерывность/продолжительность; 总是 подчеркивает частоту/привычку.\n\n一直 также может означать «прямо вперед» в направлениях: 一直走 (идти прямо вперед).", tips: ["一直 = непрерывно без остановки: 一直在学 = учился всё время.","一直 + направление = прямо: 一直走 = идти прямо вперед.","一直 vs 总是: 一直在下雨 (дождь не прекращался) vs 总是下雨 (дождь всегда идет)."], comparisons: ["一直 (непрерывно) vs 总是 (всегда — привычное) vs 常常 (часто)."] },
  75: { title: "«Вдруг» с 突然", explanation: "突然 (tūrán) означает «вдруг». Может стоять перед подлежащим или глаголом.", examples: ["Он вдруг замолчал.", "Вдруг пошёл дождь.", "Она вдруг засмеялась."], detailedExplanation: "突然 (tūrán) означает «внезапно» и может использоваться как наречие (перед глаголом) или как прилагательное (很突然 — очень внезапно). Оно подчеркивает, что что-то произошло без предупреждения.\n\nКак наречие: 突然下雨了 (Внезапно пошел дождь). 他突然不说话了 (Он внезапно перестал говорить).\n\nАкцент делается на неожиданность. Не используйте 突然 для того, что было запланировано или ожидалось — это всегда подразумевает неожиданность.", tips: ["突然 перед глаголом = внезапно: 突然停了 = внезапно остановилось.","Может стоять перед подлежащим тоже: 突然，有人敲门 = Внезапно, кто-то постучал в дверь.","Только для неожиданных событий — никогда для запланированных действий."], comparisons: ["突然 (внезапно — неожиданно) vs 马上 (немедленно — о том, что произойдет скоро)."] },
  76: { title: "«Сейчас же» с 马上", explanation: "马上 (mǎshàng) означает «сейчас же» или «немедленно».", examples: ["Я сейчас приду.", "Фильм вот-вот начнётся.", "Он сейчас вернётся."], detailedExplanation: "马上 (mǎshàng) означает 'немедленно' или 'сейчас же' и является одним из самых распространенных слов, выражающих срочность. 我马上来 (Я сейчас иду) — то, что вы говорите, когда кто-то ждет вас.\n\nОно также может означать 'сейчас начнется' для предстоящих событий: 电影马上开始 (Фильм скоро начнется). Акцент делается на очень скоро — в течение нескольких секунд или минут.\n\n马上 часто сочетается с 就: 马上就来 (Сейчас приду). 就 добавляет акцент на немедленность.", tips: ["马上 + глагол = немедленно/сейчас: 马上走 = ухожу сейчас.","马上就 добавляет акцент: 马上就好 = Скоро будет готово.","我马上来 — одно из самых практичных повседневных выражений."], comparisons: ["马上 (сейчас — секунды) vs 快要...了 (сейчас — скоро) vs 一会儿 (через некоторое время — не срочно)."] },
  77: { title: "Результативный комплемент 到", explanation: "到 (dào) как результативный комплемент означает, что действие успешно достигло цели — «найти», «достичь», «до».", examples: ["Я нашёл это.", "Ты слышал?", "Я его увидел."], detailedExplanation: "到 (dào) после глагола означает, что действие ДОСТИГЛО своей цели — оно было успешным. 找到 (поиск и нахождение), 看到 (посмотрел и увидел), 听到 (прислушался и услышал). Без 到 вы просто выполняете действие; с 到 вы достигаете результата.\n\n找 = искать. 找到 = найти (успешно). Эта разница крайне важна: 我在找 (Я ищу) против 我找到了 (Я нашел). \n\n到 также может означать «до»: 他工作到晚上十点 (Он работал до 10 вечера).", tips: ["Глагол + 到 = успешно достигнуто: 找到 (нашел), 看到 (увидел), 听到 (услышал).","找 (ищу) против 找到 (нашел). 到 обозначает успех.","到 как «до»: 等到明天 = ждать до завтра."], comparisons: ["Глагол + 到 (достигнуто/успешно) против глагола + 完 (закончено) против глагола + 好 (сделано правильно)."] },
  78: { title: "Результативный комплемент 好", explanation: "好 (hǎo) как результативный комплемент означает, что действие выполнено должным образом — «готово», «сделано».", examples: ["Еда готова.", "Ты готов?", "Домашняя работа сделана."], detailedExplanation: "好 (hǎo) после глагола означает «сделано правильно» или «готово». 做好 (готово сделать), 准备好 (приготовлено/готово), 写好 (закончено писать правильно).\n\nАкцент делается на полноте и качестве — задача выполнена удовлетворительно. 饭做好了 (Еда готова — она правильно приготовлена и готова к подаче).\n\n准备好了吗？ (Ты готов?) — одна из самых распространенных фраз, использующих эту конструкцию. Ответ: 准备好了 (Готов!) или 还没准备好 (Еще не готов).", tips: ["Глагол + 好 = сделано правильно/готово: 准备好 = готово, 做好 = готово сделать.","准备好了吗？ = Ты готов? Необходимая фраза.","Хорошо подразумевает качество; 完 просто означает завершение (независимо от качества)."], comparisons: ["Глагол + 好 (сделано правильно/готово) против глагола + 完 (завершено) против глагола + 到 (достигнуто)."] },
  79: { title: "Комплемент направления 来/去", explanation: "来 (lái) указывает движение к говорящему; 去 (qù) — от говорящего. Они следуют за основным глаголом.", examples: ["Он подбежал ко мне.", "Пожалуйста, входите.", "Он вышел."], detailedExplanation: "来 и 去 после глаголов указывают направление движения: 来 = к говорящему, 去 = от говорящего. 进来 (войти — ко мне), 进去 (войти — от меня).\n\nОни сочетаются с направляющими глаголами: 上来 (подняться), 下去 (спуститься), 出来 (выйти), 回去 (вернуться). Шаблон: движение + направление.\n\nС основным глаголом: 跑过来 (бежать сюда), 走出去 (выходить). Основной глагол описывает СПОСОБ, а 来/去 — направление относительно говорящего.", tips: ["来 = к говорящему. 去 = от говорящего.","Распространенные пары: 进来/进去, 出来/出去, 上来/上去, 回来/回去.","请进来 = Пожалуйста, войдите (ко мне). 请出去 = Пожалуйста, выйдите (от меня)."], comparisons: ["来 (к говорящему) против 去 (от говорящего). Один и тот же глагол, противоположное направление."] },
  80: { title: "Потенциальный комплемент с 得/不", explanation: "Глагол + 得 + комплемент означает «можно сделать». Глагол + 不 + комплемент означает «не получится».", examples: ["Я вижу.", "Я не понимаю на слух.", "Столько можно доесть?"], detailedExplanation: "Возможные дополнения выражают, можете ли вы достичь результата. Глагол + 得 + дополнение = можете сделать это. Глагол + 不 + дополнение = не можете сделать это.\n\n看得见 (можно увидеть — видение достигает результата «видимый»). 看不见 (нельзя увидеть). 听得懂 (можно понять, слушая). 听不懂 (нельзя понять).\n\nЭто одна из самых практичных конструкций для повседневной жизни: 听不懂 (я не понимаю, что вы говорите), 吃不完 (я не могу съесть всё это), 买不起 (я не могу позволить себе это).", tips: ["Глагол + 得 + результат = МОЖЕТЕ. Глагол + 不 + результат = НЕ МОЖЕТЕ.","听不懂 = нельзя понять. Одна из самых полезных фраз для учеников.","买不起 = нельзя позволить себе. 吃不完 = нельзя закончить есть."], comparisons: ["Возможное (看得见/看不见 — можно/нельзя увидеть) против фактического результата (看见了 — увидел)."] },
  81: { title: "Комплемент степени с 得", explanation: "得 (de) после глагола вводит описание того, как выполнено действие — его способ или результат.", examples: ["Он говорит очень хорошо.", "Она бегает очень быстро.", "Ты пишешь слишком медленно."], detailedExplanation: "Степень дополнения с 得 (де) описывает, КАК выполняется действие. Глагол + 得 + описание. 说得很好 (говорит очень хорошо), 跑得很快 (бежит очень быстро).\n\nВАЖНО: Когда есть объект, глагол должен быть повторен: 他说中文说得很好 (Он говорит китайский, говорит очень хорошо) — да, глагол появляется дважды. Или перефразируйте: 他的中文说得很好.\n\nНе путайте три «де»: 得 (после глаголов, описывает способ), 的 (после прилагательных/существительных, принадлежность), 地 (перед глаголами, описывает как). 说得好 (говорит хорошо) против好的书 (хорошая книга) против快地跑 (быстро бежать).", tips: ["Глагол + 得 + описание: 写得漂亮 = пишет красиво.","С объектом повторяйте глагол: 他说中文说得很好.","Три де: 得 (способ), 的 (принадлежность), 地 (обстоятельство)."], comparisons: ["得 (способ: 说得好) против 的 (принадлежность: 好的) против 地 (обстоятельство: 快地走)."] },
  82: { title: "Конструкция с 把", explanation: "把 (bǎ) выносит дополнение перед глаголом, чтобы подчеркнуть, что с ним происходит. Глагол должен иметь результат или направление.", examples: ["Пожалуйста, закройте дверь.", "Он положил книгу на стол.", "Я сделал домашнее задание."], detailedExplanation: "Конструкция 把 перемещает объект перед глаголом, чтобы подчеркнуть, что с ним происходит. Обычный порядок: 我关门了 (Я закрыл дверь). Конструкция 把: 我把门关上了 (Я закрыл дверь — акцент на том, что дверь была обработана).\n\nКлючевое правило: глагол в предложении с 把 НЕ МОЖЕТ быть без дополнения — он должен иметь дополнение (результат, направление, 了 и т.д.). 请把门关 — неполное предложение; 请把门关上 — правильно.\n\nКонструкция 把 особенно полезна для инструкций: 把书打开 (Откройте книгу), 把灯关了 (Выключите свет), 把这个吃了 (Съешьте это).", tips: ["把 + объект + глагол + дополнение. Глагол не может быть без дополнения.","Используйте для утилизации/обработки: 把垃圾扔了 = Выбросьте мусор.","Часто используется в инструкциях: 把门关上, 把书打开, 把作业做完."], comparisons: ["把 (сделать что-то с объектом) против обычного порядка слов (нейтральное утверждение)."] },
  83: { title: "Страдательный залог с 被", explanation: "被 (bèi) обозначает страдательный залог. Подлежащее испытывает действие. Часто подразумевается что-то нежелательное.", examples: ["Мой телефон украли.", "Торт съел он.", "Ту книгу кто-то взял."], detailedExplanation: "被 (bèi) обозначает ПАССИВНЫЙ ЗАЛОГ — подлежащее испытывает действие, а не совершает его. 我的手机被偷了 (Мой телефон был украден). Телефон является жертвой кражи.\n\nКультурная заметка: традиционно 被 подразумевает что-то НЕГАТИВНОЕ или нежелательное, случившееся с подлежащим. 被偷 (украдено), 被骂 (ругано), 被打 (ударено). В современном китайском нейтральные/положительные пассивные формы становятся всё более распространенными (被选为 = избран как), но негативная окраска всё ещё является стандартной.\n\nАгент (кто это сделал) может отсутствовать: 手机被偷了 (телефон был украден — кем-то неизвестным) против 手机被他偷了 (телефон был украден им).", tips: ["被 обычно подразумевает что-то плохое: 被骗 (обманут), 被偷 (украдено).","Агент может отсутствовать: 被偷了 (украдено) или 被他偷了 (украдено им).","Современное использование: 被 сейчас используется более нейтрально, но негативная окраска всё ещё является стандартной."], comparisons: ["被 (пассив — действия, совершённые НАД вами) против 把 (актив — вы совершаете действия НАД объектами)."] },
  84: { title: "«Позволять / заставлять» с 让", explanation: "让 (ràng) означает «позволять» или «заставлять кого-то делать что-то».", examples: ["Мама заставляет меня учиться.", "Дай мне подумать.", "Учитель не разрешает нам разговаривать."], detailedExplanation: "让 (ràng) означает 'позволить' или 'заставить кого-то что-то сделать'. Субъект + 让 + человек + глагол. 妈妈让我学习 (Мама заставляет меня учиться). 让我想想 (Позвольте мне подумать).\n\n让 охватывает и 'разрешить' (позволить), и 'вызвать' (заставить), в зависимости от контекста. 老师不让我们说话 (Учитель не разрешает нам говорить — запрет). 这件事让我很开心 (Это событие заставляет меня быть очень счастливым — причинность).\n\n让 более мягкий, чем 叫 (jiào), который также означает 'заставить кого-то сделать', но более настоятельный/разговорный.", tips: ["让 + человек + глагол: 让我看看 = Позвольте мне посмотреть.","让 = позволить (разрешение) или заставить (причинность), в зависимости от контекста.","让 (нейтральный/вежливый) против 叫 (более настоятельный/разговорный). Оба означают 'заставить кого-то сделать'."], comparisons: ["让 (позволить/заставить — нейтральный) против 叫 (заставить — более настоятельный) против 请 (пожалуйста — вежливая просьба)."] },
  85: { title: "«От…до» с 从…到", explanation: "从 (cóng) означает «от», а 到 (dào) — «до». Используется для временных и пространственных диапазонов.", examples: ["Отсюда до школы близко.", "С утра до вечера.", "Я еду поездом из Пекина в Шанхай."], detailedExplanation: "从...到... обозначает диапазон — от начальной точки ДО конечной точки. Работает как для мест, так и для времени.\n\nМесто: 从北京到上海 (от Пекина до Шанхая). Время: 从早上到晚上 (с утра до вечера). Оба: 从三点到五点 (с трех до пяти часов).\n\n从 отдельно означает «от» как предлог: 我从中国来 (Я приехал из Китая). Он всегда указывает на источник или начальную точку.", tips: ["从 A 到 B: работает для мест, времени и абстрактных диапазонов.","从 отдельно = от: 我从北京来 = Я приехал из Пекина.","从...到... может выражать трансформацию: 从小到大 = от детства до взросления."], comparisons: ["从...到 (от... до — диапазон) против 离 (расстояние от: 离这儿很近)."] },
  86: { title: "«В направлении» с 向 и 往", explanation: "向 (xiàng) и 往 (wǎng) оба означают «в направлении». 往 чаще для физического направления; 向 также для абстрактных целей.", examples: ["Идите прямо.", "Поверните налево.", "Он пошёл ко мне."] },
  87: { title: "Двойное 了: продолжающееся действие", explanation: "Два 了 — один после глагола и один в конце — означают, что действие началось в прошлом и всё ещё продолжается.", examples: ["Я учу китайский уже три года.", "Он ждёт уже два часа.", "Мы живём здесь уже пять лет."], detailedExplanation: "Двойной 了 — один после глагола и один в конце предложения — означает, что действие началось в прошлом и ПРОДОЛЖАЕТСЯ ДО СЕГОДНЯ. 我学了三年中文了 (Я изучаю китайский уже три года — и продолжаю изучать).\n\nБез второго 了: 我学了三年中文 (Я изучал китайский три года — возможно, это уже закончено). Второй 了 как раз указывает на продолжение до настоящего времени.\n\nЭта конструкция важна для выражения продолжительности текущих действий. Она отвечает на вопрос 'сколько времени вы уже...?': 你学了多长时间了? (Сколько времени вы уже изучаете?).", tips: ["Двойной 了 = началось в прошлом, продолжается сейчас: 等了两个小时了 = ждал два часа.","Одиночный 了 = прошедшая продолжительность (может быть закончена). Двойной 了 = продолжается до сих пор.","Частый вопрос: 你学了多长时间了? = Сколько времени вы уже изучаете?"], comparisons: ["学了三年 (изучал три года — возможно, закончил) vs 学了三年了 (изучает уже три года — продолжает)."] },
  88: { title: "Выражение длительности", explanation: "Длительность ставится после глагола. Если есть дополнение, глагол либо повторяется, либо перед дополнением добавляется 的.", examples: ["Я учусь по два часа каждый день.", "Он проспал восемь часов.", "Я читал час."], detailedExplanation: "В китайском языке продолжительность времени ставится ПОСЛЕ глагола, что отличается от английского. 我学了两个小时 (Я учился два часа) — продолжительность следует за глаголом.\n\nС объектом всё становится сложнее. Три варианта: (1) Повторить глагол: 我看书看了一个小时. (2) Добавить 的: 我看了一个小时的书. (3) Если объект короткий или понятен из контекста, просто добавить: 他睡了八个小时.\n\nПродолжительность выражается с использованием мерных слов: 小时 (час), 天 (день), 个星期 (неделя), 个月 (месяц), 年 (год). Два часа — 两个小时, три дня — 三天.", tips: ["Продолжительность ставится ПОСЛЕ глагола: 学了三年 = учился три года.","С объектом повторяйте глагол или добавляйте 的: 看了一个小时的书.","Мерные слова для продолжительности: 小时 (час), 天 (день), 个星期 (неделя), 个月 (месяц), 年 (год)."], comparisons: ["Продолжительность после глагола (学了三年) против фразы времени перед глаголом (三点学 = учиться в три часа)."] },
  89: { title: "Выражение частоты с 每", explanation: "每 (měi) означает «каждый». 都 часто следует за ним для усиления — «всегда», «каждый раз».", examples: ["Я занимаюсь спортом каждый день.", "Он ходит туда каждую неделю.", "Все пришли."], detailedExplanation: "每 (měi) означает 'каждый' и используется для рутин и привычек. Паттерн стандартный: 每 + слово времени + 都 + глагол: 我每天都运动 (Я занимаюсь спортом каждый день).\n\n都 после слова времени подчеркивает 'без исключения'. Можно опустить 都, но тогда звучит менее эмоционально: 我每天运动 (Я занимаюсь спортом каждый день — чуть менее подчеркнуто).\n\n每 требует меры перед существительными: 每个人 (каждый человек), 每本书 (каждая книга). Но не перед словами времени: 每天, 每年, 每周.", tips: ["每 + время + 都 + глагол: 每天都学习 = учиться каждый день.","每 + мера + существительное: 每个人 (каждый человек), 每本书 (каждая книга).","都 добавляет 'без исключения': 每次都迟到 = опаздывать каждый раз."], comparisons: ["每 (каждый — рутина) vs 所有 (все — полнота) vs 都 (все — обобщение)."] },
  90: { title: "«Одновременно» с 一边…一边", explanation: "一边…一边 (yìbiān…yìbiān) означает выполнение двух действий одновременно.", examples: ["Он ест и смотрит телевизор.", "Она идёт и разговаривает по телефону.", "Я слушаю музыку и учусь."], detailedExplanation: "一边...一边... описывает два действия, происходящие ОДНОВРЕМЕННО. 一边吃饭一边看电视 (есть, пока смотришь телевизор). Оба действия продолжаются в одно и то же время.\n\nДва действия должны быть физически возможны для совместного выполнения. Вы можете 一边走一边说话 (идти, разговаривая), но не 一边睡觉一边跑步 (спать, бегая).\n\nВ неформальной речи иногда используется только 一边 для первого действия: 他吃饭，一边看手机 — но полная конструкция более ясна.", tips: ["一边 A 一边 B = делать A, пока делаешь B одновременно.","Оба действия должны быть физически совместимы.","Часто используется: 一边听音乐一边学习, 一边走一边聊天."], comparisons: ["一边...一边 (одновременные действия) против 先...然后 (последовательные — сначала... потом)."] },
  91: { title: "Выражение цели с 为了", explanation: "为了 (wèile) означает «для того чтобы». Указывает цель или причину действия.", examples: ["Чтобы выучить китайский, я приехал в Китай.", "Он занимается ради экзамена.", "Ради здоровья нужно больше заниматься спортом."], detailedExplanation: "为了 (wèile) указывает НАЗНАЧЕНИЕ действия — «ради». Обычно он стоит в начале предложения: 为了学中文，我来了中国 (Ради изучения китайского языка я приехал в Китай).\n\nПредложение с целью, начинающееся с 为了, идет ДО основного действия. Это соответствует логике китайского языка: сначала цель, потом действие.\n\nНе путайте 为了 (ради — цель) с 因为 (потому что — причина). 为了 смотрит вперед (цель), 因为 смотрит назад (причина).", tips: ["为了 + цель, + действие: 为了健康，多运动 = Ради здоровья, больше двигайтесь.","为了 указывает цель. 因为 указывает причину. Разные направления.","为了 стоит перед основным предложением, задавая цель первым."], comparisons: ["为了 (ради — направлено вперед к цели) против 因为 (потому что — направлено назад к причине)."] },
  92: { title: "«Зависит от» с 看", explanation: "看 (kàn) может означать «зависит от». После 看 следует то, от чего зависит результат.", examples: ["Зависит от погоды.", "Зависит от того, куда ты хочешь поехать.", "Пойду или нет — зависит от обстоятельств."], detailedExplanation: "看 (kàn) за ним следует вопросительное предложение, что означает «зависит от» или «давай посмотрим». 看天气吧 (Зависит от погоды). 看情况 (Зависит от ситуации).\n\nЭто чрезвычайно естественный способ выразить неуверенность или гибкость. Вместо того чтобы принимать решение сразу, вы откладываете его до обстоятельств. Очень распространено в повседневном китайском языке.\n\nЗдесь 看 не означает буквально «смотреть» — это «рассмотреть/учесть». 我们看看吧 (Давай посмотрим) — полезная фраза для вежливого откладывания решений.", tips: ["看 + фактор = зависит от: 看你的时间 = зависит от вашего графика.","看情况 и 看看吧 — самые распространенные фразы для «зависит» / «давай посмотрим».","Этот 看 означает «рассмотреть», а не буквально «посмотреть»."], comparisons: ["看 (зависит от — рассматривая) против 要看 (нужно посмотреть — немного более формально)."] },
  93: { title: "Продолжающееся состояние с 着", explanation: "着 (zhe) указывает на состояние, возникшее в результате действия — действие произошло, и состояние сохраняется.", examples: ["Дверь открыта.", "Он стоит.", "На стене висит картина."] },
};
